24:       links;
25: 
26:   if (!state.md.options.linkify) { return; }
27: 
28:   for (j = 0, l = blockTokens.length; j < l; j++) {
29:     if (blockTokens[j].type !== 'inline') { continue; }
30: 
31:     tokens = blockTokens[j].children;
32: 
33:     htmlLinkLevel = 0;
34: 
35:     // We scan from the end, to keep position when new tags added.
36:     // Use reversed logic in links start/end match
37:     for (i = tokens.length - 1; i >= 0; i--) {
38:       currentToken = tokens[i];
